#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>

int main() {
  int fd = open("my_file.txt", O_RDONLY);
  if (fd == -1) { perror("open"); return 1; }
  printf("Parent: File descriptor: %d\n", fd);

  pid_t pid = fork();
  if (pid < 0) { perror("fork"); return 1; }
  else if (pid == 0) {
    printf("Child: File descriptor: %d\n", fd);
    //Child process reads from the file using the inherited fd
  } else {
    //Parent process continues...
  }
  close(fd); //Important: Parent should close the descriptor when done
  return 0;
}
